configuration.tbelScript:
function containsVal(arr, v) {
  for (x : arr) {
    if (('' + x) == ('' + v)) { return true; }
  }
  return false;
}
function addUnique(arr, v) {
  if (!containsVal(arr, v)) { arr.add(v); }
}
function splitCsv(s) {
  var out = [];
  if (s == null) { return out; }
  var parts = ('' + s).split(',');
  for (p : parts) {
    var t = ('' + p).trim();
    if (t != '') { out.add(t); }
  }
  return out;
}
function diff(a, b) {
  var out = [];
  for (x : a) {
    if (!containsVal(b, x)) { out.add(x); }
  }
  return out;
}

var nicActive = [];
var mappedActive = msg['mappedActiveAlarms'];
if (mappedActive != null) {
  for (a : mappedActive) {
    if (a != null && a['canonicalAlarm'] != null) {
      addUnique(nicActive, a['canonicalAlarm']);
    }
  }
}

var tbActive = [];
var tbRaw = msg['tb.active_alarm_types'];
if (tbRaw == null) { tbRaw = metadata['tb.active_alarm_types']; }
if (tbRaw != null) {
  if (tbRaw.size != null) {
    for (x : tbRaw) { if (x != null) { addUnique(tbActive, '' + x); } }
  } else {
    var tbStr = '' + tbRaw;
    if (tbStr.startsWith('[')) {
      var parsed = JSON.parse(tbStr);
      if (parsed != null) {
        for (x : parsed) { if (x != null) { addUnique(tbActive, '' + x); } }
      }
    } else {
      var csv = splitCsv(tbStr);
      for (x : csv) { addUnique(tbActive, x); }
    }
  }
}

var onlyInDevice = diff(nicActive, tbActive);
var onlyInTb = diff(tbActive, nicActive);
var inSync = (onlyInDevice.size() == 0 && onlyInTb.size() == 0);

var nowTs = msg['ts'];
if (nowTs == null) { nowTs = metadata['ts']; }

var out = {
  'alarm.sync.nic_active': JSON.stringify(nicActive),
  'alarm.sync.tb_active': JSON.stringify(tbActive),
  'alarm.sync.only_in_device': JSON.stringify(onlyInDevice),
  'alarm.sync.only_in_tb': JSON.stringify(onlyInTb),
  'alarm.sync.only_in_device_count': onlyInDevice.size(),
  'alarm.sync.only_in_tb_count': onlyInTb.size(),
  'alarm.sync.in_sync': inSync,
  'alarm.sync.last_ts': nowTs
};

return {msg: out, metadata: metadata, msgType: 'Post telemetry'};
